INSERT INTO courses.steps (id, lesson_id, type, title, content, order_index, created_at, updated_at)
VALUES ('21126ca1-c8ba-55df-ac9a-ab2eaf343118', '2f058c51-5963-5c21-9102-5c4eba41c847', 'text', 'Vocabulary', '{"text": "## My Job Title\n\n**Job** — Your professional work.\n_I love my new job._\n\n**Title** — The official name of your work role.\n_My job title is Manager._\n\n**Am** — The verb ''to be'' used only with ''I''.\n_I am a worker here._\n\n**Is** — The verb ''to be'' used for one person (he/she/it).\n_He is an engineer._\n\n**Teacher** — A person who helps students learn.\n_She is an English teacher._\n\n**Manager** — A person who directs a team or office.\n_He is a good manager._\n\n**Engineer** — A person who designs or builds machines and systems.\n_I am an engineer._\n\n**Worker** — A person who does a specific job in a company.\n_He is a hard worker._\n\n**A** — Used before a job starting with a consonant sound.\n_I am a designer._\n\n**An** — Used before a job starting with a vowel sound.\n_She is an accountant._\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
