INSERT INTO courses.steps (id, lesson_id, type, title, content, order_index, created_at, updated_at)
VALUES ('9605f659-b289-5ad7-af45-deb3bf683cc2', '36d4b277-bbcf-5d5c-95b5-eb4a3e8c1daf', 'text', 'Vocabulary', '{"text": "## Meeting the Team\n\n**Team** — A group of people working together.\n_This is our marketing team._\n\n**Meet** — To see and know a person for the first time.\n_Nice to meet you._\n\n**Colleague** — A person you work with.\n_Anna is my colleague._\n\n**Coworker** — Another word for someone who works in your office.\n_My coworker is busy._\n\n**Boss** — The person in charge of the workers.\n_The boss is in the room._\n\n**This** — Used to introduce a person close to you.\n_This is my partner, Alex._\n\n**Our** — Belonging to us.\n_Welcome to our clean office._\n\n**Hello** — A professional greeting.\n_Hello, my name is Mr. Abdul._\n\n**New** — Someone who just started at the company.\n_We have a new worker today._\n\n**Staff** — All the people who work for a company.\n_The office staff is very kind._\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
