INSERT INTO courses.steps (id, lesson_id, type, title, content, order_index, created_at, updated_at)
VALUES ('c89dae41-c961-573c-a097-8126ef2effd7', 'd5fd493a-db7d-5370-a4bd-f98cc01e1a62', 'text', 'Vocabulary', '{"text": "## In My Desk Drawer\n\n**Drawer** — A sliding box in your desk for storage.\n_The keys are in the drawer._\n\n**In** — Inside a container or location.\n_The notebook is in the bag._\n\n**Notebook** — A small book with empty pages for writing notes.\n_I open my notebook._\n\n**Pencil** — A wooden instrument used for writing or drawing.\n_I write with a pencil._\n\n**Key** — A metal object used to open locked doors or drawers.\n_Here is your office key._\n\n**Scissors** — A tool used for cutting paper.\n_The scissors are on the table._\n\n**Stapler** — A small device used to fasten papers together.\n_I need a stapler for this report._\n\n**Folder** — A plastic or paper cover to hold documents.\n_Put the file in the folder._\n\n**Glue** — A liquid substance used to paste papers together.\n_The glue is in the drawer._\n\n**Under** — Below something else.\n_The bag is under the chair._\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
