INSERT INTO courses.steps (id, lesson_id, type, title, content, order_index, created_at, updated_at)
VALUES ('cb3571ff-1a03-5ea0-afc5-aced07b1673b', '2fd57295-9a67-5f7e-beb4-91ecc959999b', 'text', 'Vocabulary', '{"text": "## The Company Name\n\n**Company** — A business that sells products or services.\n_Our company is big._\n\n**Name** — The word that identifies a business or person.\n_What is the company name?_\n\n**Work** — To perform tasks for a job.\n_I work at a logistics firm._\n\n**At** — Used to show a specific place of employment.\n_She works at Google._\n\n**For** — Working on behalf of an employer.\n_He works for a modern factory._\n\n**Small** — Not big; limited in size.\n_This is a small startup company._\n\n**Big** — Large in size or operation.\n_They work for a big international firm._\n\n**Brand** — The public identity of a business.\n_We have a premium brand._\n\n**Local** — Related to the nearby city or area.\n_It is a local business._\n\n**Global** — Operating worldwide across many countries.\n_Our company is a global brand._\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
