INSERT INTO courses.steps (id, lesson_id, type, title, content, order_index, created_at, updated_at)
VALUES ('b477ceb1-04ae-5a91-a2ec-7a64c49d7200', '3cf04ca7-ca5a-5043-a4c4-92e76b482cab', 'text', 'Vocabulary', '{"text": "## Contact Details\n\n**Email** — A digital message or address used for work communication.\n_Send me an email._\n\n**Number** — Digits used to call a phone.\n_What is your office phone number?_\n\n**Address** — The physical location of the office building.\n_Write down the company address._\n\n**Spell** — To say the letters of a word one by one.\n_Can you spell your name, please?_\n\n**Write** — To put words on paper or a computer screen.\n_Please write your email here._\n\n**Sign** — To write your official signature on a document.\n_Please sign this paper._\n\n**Contact** — Information used to reach someone.\n_Here are my business contact details._\n\n**Letter** — A single character of the alphabet (A, B, C).\n_My name starts with the letter A._\n\n**Dot** — The spoken word for a period (.) in an email address.\n_My email is info dot com._\n\n**At-sign** — The spoken word for the symbol (@) in an email address.\n_Write the at-sign clearly._\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
