INSERT INTO courses.steps (id, lesson_id, type, title, content, order_index, created_at, updated_at)
VALUES ('0e72a320-27a0-51ef-8a53-ea6390882f24', 'e2ba90fc-fd4f-592b-89c5-b356a7339640', 'text', 'Vocabulary', '{"text": "## My Work Schedule\n\n**Days** — The 24-hour periods of the week.\n_I work five days a week._\n\n**Hours** — The time units spent working.\n_My work hours are 9 to 5._\n\n**Start** — To begin a task or a workday.\n_I start work at 9:00 AM._\n\n**Finish** — To end a task or a workday.\n_We finish work early on Fridays._\n\n**Calendar** — A chart showing the days, weeks, and months of the year.\n_Check the office calendar._\n\n**Monday** — The first working day of the week.\n_The team meeting is on Monday._\n\n**Friday** — The final standard working day of the week.\n_I am happy on Friday afternoon._\n\n**Weekend** — Saturday and Sunday when most people do not work.\n_I rest on the weekend._\n\n**Time** — The specific hour on a clock.\n_What time does the meeting start?_\n\n**Schedule** — A plan of times and days for work.\n_My daily work schedule is busy._\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
