INSERT INTO courses.steps (id, lesson_id, type, title, content, order_index, created_at, updated_at)
VALUES ('0e43762f-fecc-552d-a627-841a9f1c79b9', '64651d49-c8c7-5fbb-9c8f-1722c79d0d8d', 'text', 'Vocabulary', '{"text": "## Saying Hello & Goodbye\n\n**Morning** — The early part of the day before 12:00 PM.\n_Good morning, team!_\n\n**Afternoon** — The part of the day between noon and evening.\n_Good afternoon, Mr. Abdul._\n\n**Welcome** — A warm greeting to someone arriving at work.\n_Welcome to our new office._\n\n**Goodbye** — Said when leaving a person or workplace.\n_Goodbye, see you tomorrow._\n\n**Please** — A polite word used to ask for things.\n_Open the door, please._\n\n**Thank you** — An expression of gratitude at work.\n_Thank you for the helpful report._\n\n**Fine** — Feeling okay or in a good state.\n_I am fine, thank you._\n\n**Day** — A professional wish for someone''s daylight hours.\n_Have a nice day!_\n\n**Evening** — The late part of the day after work hours.\n_Good evening, director._\n\n**See** — To look at or meet someone again.\n_See you on Monday morning._\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
