INSERT INTO courses.steps (id, lesson_id, type, title, content, order_index, created_at, updated_at)
VALUES ('2a90934f-2981-5a1a-86bb-4bbbd602f7eb', '70e0a4e2-c61b-5b19-9dd8-cb362dacfe45', 'text', 'Vocabulary', '{"text": "## The Office Kitchen\n\n**Kitchen** — The room where employees make drinks and store food.\n_The kitchen is clean._\n\n**Coffee** — A popular hot dark work drink.\n_I need a warm cup of coffee._\n\n**Tea** — A hot drink made from dried leaves.\n_She drinks green tea during the break._\n\n**Water** — Clear liquid necessary for drinking.\n_There is fresh water in the kitchen._\n\n**Cup** — A container used for hot drinks like coffee or tea.\n_Your cup is on the table._\n\n**Mug** — A large cup with a handle used in offices.\n_This is my favorite office mug._\n\n**Sugar** — Sweet white crystals added to drinks.\n_Do you want sugar in your tea?_\n\n**Milk** — A white liquid added to coffee or tea.\n_The milk is in the refrigerator._\n\n**Clean** — Free from dirt or mess.\n_Please keep the office kitchen clean._\n\n**Break** — A short rest time from work duties.\n_Let''s take a quick 10-minute break._\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
