INSERT INTO courses.steps (id, lesson_id, type, title, content, order_index, created_at, updated_at)
VALUES ('afbf5ed5-878c-578d-8ad1-44167389d275', 'b96043a3-9c41-508f-a811-7cf71faf9951', 'text', 'Vocabulary', '{"text": "## Clocking In\n\n**Early** — Arriving before the official scheduled time.\n_He is early for the client call._\n\n**Late** — Arriving after the official scheduled time.\n_Please do not be late for work._\n\n**On-time** — Arriving exactly at the correct planned hour.\n_A professional is always on-time._\n\n**Clock** — The wall device that shows the current time.\n_Look at the office clock._\n\n**Watch** — A small clock worn on your wrist.\n_I check the time on my watch._\n\n**Card** — A plastic pass used to log into the building entry scanner.\n_Scan your work card here._\n\n**Arrive** — To reach the workspace destination.\n_What time do you arrive at the office?_\n\n**Now** — At the present immediate moment.\n_The manager wants to see you now._\n\n**Minute** — A unit of time equal to 60 seconds.\n_Give me one minute, please._\n\n**Log** — To sign into a system or record attendance.\n_I log my hours on the computer every day._\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
