INSERT INTO courses.steps (id, lesson_id, type, title, content, order_index, created_at, updated_at)
VALUES ('a31783ad-0d8f-59d4-8770-2c90115ff7c0', '6b343d55-ec19-58d4-9bc2-e3bca24a0eae', 'text', 'Vocabulary', '{"text": "## Checking Email\n\n**Check** — To look at something to find information.\n_I check my email every morning._\n\n**Read** — To look at written words and understand them.\n_Please read this message._\n\n**New** — Received just now or recently.\n_You have five new emails today._\n\n**Subject** — The main title or topic of an email message.\n_The email subject line is ''Meeting''._\n\n**Open** — To unseal or view a digital document or app.\n_Open the email attachment, please._\n\n**Inbox** — The digital folder where new emails arrive.\n_My corporate inbox is completely full._\n\n**Message** — A short piece of information sent to someone.\n_I am reading a message from a client._\n\n**From** — Showing who sent the communication.\n_This official email is from the manager._\n\n**Reply** — To write back or answer an email.\n_I need to reply to this email now._\n\n**Send** — To pass a digital message to another person.\n_Send the final document to my colleague._\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
