INSERT INTO courses.steps (id, lesson_id, type, title, content, order_index, created_at, updated_at)
VALUES ('d17f9580-3dc2-56dc-be89-adfb1ce4a166', '40d0f6e5-683c-5471-bbf8-281e5ce6722d', 'text', 'Vocabulary', '{"text": "## Answering Phone Calls\n\n**Call** — A telephonic conversation request.\n_You have a phone call from a customer._\n\n**Ring** — Making a sound to signal an incoming call.\n_The office phone is starting to ring._\n\n**Answer** — To pick up the phone and speak.\n_Please answer the office phone._\n\n**Speak** — To talk or communicate using your voice.\n_Can I speak to Mr. Abdul, please?_\n\n**Hear** — To receive sound with your ears.\n_I cannot hear you clearly on this line._\n\n**Line** — The telephone connection.\n_Please hold, the line is currently busy._\n\n**Wait** — To stay in one place until a later time.\n_Wait a minute for the manager, please._\n\n**Hello** — The standard polite word to answer a phone.\n_Hello, this is the sales department._\n\n**Goodbye** — The phrase used to end a conversation.\n_Thank you for calling, goodbye._\n\n**Who** — Asking about the identity of a person.\n_Who is calling the office right now?_\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
