INSERT INTO courses.steps (id, lesson_id, type, title, content, order_index, created_at, updated_at)
VALUES ('8b749092-4baa-5c02-ae2e-d47bfe2d5ea2', 'bacbe819-2b0f-5ca7-ad14-c0dedb5cb5e2', 'text', 'Vocabulary', '{"text": "## Writing a To-Do List\n\n**List** — A set of words written down one below the other.\n_Look at my daily work list._\n\n**Task** — A specific piece of work that you must complete.\n_This is my main task today._\n\n**Plan** — A set of actions intended to achieve something.\n_We have a clean plan for the project._\n\n**Notebook** — A paper book used for logging items.\n_I write my tasks inside a notebook._\n\n**First** — Coming before all others in time or order.\n_First, I check my office inbox._\n\n**Next** — Coming immediately after something else.\n_Next, I print out the client documents._\n\n**Then** — Used to show the sequence of next actions.\n_Then, I call our international partner._\n\n**Done** — Finished or completed successfully.\n_This urgent task is finally done._\n\n**Important** — Valuable or requiring immediate attention.\n_This is an important contract._\n\n**Today** — The present day we are in.\n_What are your specific goals today?_\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
