INSERT INTO courses.steps (id, lesson_id, type, title, content, order_index, created_at, updated_at)
VALUES ('df021a97-6cad-53b0-89b8-20ca4666fb89', 'b70a9c39-68a5-58be-bf93-9c98ce01a879', 'text', 'Vocabulary', '{"text": "## Asking for Help\n\n**Help** — To assist someone with a task or problem.\n_Can you help me with this program?_\n\n**Please** — A word used to turn a demand into a polite request.\n_Help me coat the files, please._\n\n**Me** — The objective form of the pronoun ''I''.\n_Show me the new logistics map._\n\n**Question** — A sentence asked to get information.\n_I have a brief question about the app._\n\n**Understand** — To know the meaning of something clearly.\n_I do not understand this document._\n\n**Problem** — A situation or matter that causes difficulty.\n_We have a small system problem._\n\n**Show** — To point out or guide someone through a visual action.\n_Show me how to scan this card._\n\n**Know** — To have information or skill in your mind.\n_Do you know the new Wi-Fi password?_\n\n**Repeat** — To say or do something again.\n_Can you repeat the client name, please?_\n\n**Sorry** — A word used to express regret or ask for a repetition politely.\n_Sorry, I am new to this role._\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
