INSERT INTO courses.steps (id, lesson_id, type, title, content, order_index, created_at, updated_at)
VALUES ('6ba2126d-2221-5e35-914e-8c3474264a89', 'deb0847f-b497-555d-ae97-607cdb05b7e9', 'text', 'Vocabulary', '{"text": "## Giving Simple Updates\n\n**Update** — Current dynamic information about a project''s status.\n_Here is my weekly update._\n\n**Ready** — Completely prepared for immediate use.\n_The export report is ready now._\n\n**Finish** — To complete the final part of a task.\n_I finish the document layout at noon._\n\n**Start** — To begin working on an activity.\n_I start the code testing tomorrow._\n\n**Good** — Positive, high-quality, or successful.\n_We have very good news from the buyer._\n\n**Progress** — Movement forward toward a completion target.\n_Our development team is making progress._\n\n**Later** — At a time in the future, not right now.\n_I can discuss the contract details later._\n\n**Complete** — Finished or having all necessary parts.\n_The customer profile database is complete._\n\n**Work** — Running, operating, or performing properly.\n_The office printer is working now._\n\n**Still** — Continuing up to the present moment.\n_He is still in the director''s office._\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
