INSERT INTO courses.steps (id, lesson_id, type, title, content, order_index, created_at, updated_at)
VALUES ('40fddd1d-acaa-5502-98d0-accfa1259b68', '904273f0-6203-5df8-a7fc-14ea8d2178d6', 'text', 'Vocabulary', '{"text": "## The Office Printer\n\n**Printer** — A machine that puts text and images from a computer onto paper.\n_The printer is near the desk._\n\n**Print** — To produce a hard copy on paper using a machine.\n_Please print two copies of this._\n\n**Copy** — A duplicate version of an original paper document.\n_I need a copy of the contract._\n\n**Paper** — Sheets of material used to print out files.\n_Put white paper into the machine._\n\n**Scan** — To turn a physical paper document into a digital file.\n_Scan this official receipt, please._\n\n**Out** — Lacking or completely empty of a supply.\n_The machine is out of paper._\n\n**Ink** — The colored liquid used inside a printer for writing text.\n_We need to buy new black ink._\n\n**Button** — A small part you press to operate an electronic machine.\n_Press the big green button._\n\n**Turn on** — To connect a machine to power so it starts working.\n_Turn on the printer, please._\n\n**Machine** — A mechanical device that uses power to do work.\n_This copy machine is very fast._\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
