INSERT INTO courses.steps (id, lesson_id, type, title, content, order_index, created_at, updated_at)
VALUES ('7ce9017c-b503-5ba4-97c0-a35ab44db1b2', 'a6f9fd8c-5cb3-5dde-8f37-1c4fdbdb583b', 'text', 'Vocabulary', '{"text": "## Booking a Meeting Room\n\n**Book** — To reserve something in advance for a specific time.\n_I need to book a room._\n\n**Meeting** — An event where a team comes together to talk about work.\n_We have a meeting at 2 PM._\n\n**Room** — A closed workspace walled off inside a building.\n_The small room is empty now._\n\n**Available** — Free to be used, vacant, or unoccupied.\n_Is the conference room available?_\n\n**Time** — The hour and minute on the clock.\n_What time is the partner meeting?_\n\n**Calendar** — A system tool used to coordinate dates and schedules.\n_Check the digital calendar._\n\n**Reserve** — To save or hold a space for a particular person or group.\n_Reserve this desk for our guest._\n\n**Hour** — A specific 60-minute block of time.\n_We need the room for one hour._\n\n**Occupied** — In use by someone else; not free.\n_The large meeting room is occupied._\n\n**Calendar** — A software tool used to organize events.\n_Put the appointment in the calendar._\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
