INSERT INTO courses.steps (id, lesson_id, type, title, content, order_index, created_at, updated_at)
VALUES ('21acb0d9-d67d-5aca-aa23-35b6e61b7bf1', 'eb20a15c-fee9-564c-941b-a8e18a2aa0af', 'text', 'Vocabulary', '{"text": "## Welcome a Client\n\n**Welcome** — A polite greeting to make a visitor feel comfortable.\n_Welcome to our firm, sir._\n\n**Client** — A customer who pays for professional business services.\n_The client is at reception._\n\n**Guest** — A visitor invited to your corporate office workspace.\n_Please guide our guest to the couch._\n\n**Seat** — A chair or place to sit down.\n_Please take a comfortable seat here._\n\n**Offer** — To ask if someone wants a drink, food, or assistance.\n_Offer some green tea to the client._\n\n**Drink** — A liquid prepared for human consumption.\n_Would you like a warm drink?_\n\n**Coffee** — A standard hot workplace beverage.\n_I can make a fresh cup of coffee._\n\n**Wait** — To stay in a reception area until an official arrives.\n_The director asks you to wait here._\n\n**Meet** — To come face-to-face with a partner or consumer.\n_The boss is ready to meet you._\n\n**Right this way** — A polite phrase used to guide a visitor where to walk.\n_Follow me, right this way._\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
