INSERT INTO courses.steps (id, lesson_id, type, title, content, order_index, created_at, updated_at)
VALUES ('7a43cf36-8f37-5618-89fd-9235b3eebf38', '48f7d61f-70aa-58fd-b6c9-ee50921b08d9', 'text', 'Vocabulary', '{"text": "## Leaving a Message\n\n**Leave** — To walk away from or deposit something for later collection.\n_Can I leave a message?_\n\n**Message** — Information left for an official who is currently away.\n_Write a short note or message._\n\n**Out** — Not present inside the physical office space.\n_The manager is out at the moment._\n\n**Back** — Returning to the original place or position.\n_He will be back in the office at 3:00._\n\n**Note** — A small written message left on a desk sheet.\n_I am putting a sticky note on your computer._\n\n**Tell** — To inform or pass oral information to a person.\n_Tell him that the buyer called._\n\n**Call back** — To make a return phone call to someone later.\n_I will call back tomorrow afternoon._\n\n**Name** — Your identity word used to identify who left the memo.\n_Please write down your full name._\n\n**Busy** — Actively doing work tasks and not free to talk.\n_The assistant is extremely busy now._\n\n**Take** — To receive or write down notes for someone else.\n_I can take your message down._\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
