INSERT INTO courses.steps (id, lesson_id, type, title, content, order_index, created_at, updated_at)
VALUES ('1ec064b8-6835-52fc-839f-b3f8af374046', 'b9cacd83-478d-5175-93a6-66da08e52116', 'text', 'Vocabulary', '{"text": "## Digital Texting Tools\n\n**Chat** — A casual short digital text exchange.\n_Send me a message in the team chat._\n\n**App** — A software program downloaded onto a mobile phone.\n_We use a sleek communication app._\n\n**Link** — A digital address that opens a specific internet page.\n_Click the link to join the stream._\n\n**File** — A digital document, image, or item sent on a computer.\n_I am uploading the budget file._\n\n**Group** — A digital chat space containing multiple coworkers.\n_Post the update inside the office group._\n\n**Online** — Connected to the internet or available right now inside the app.\n_The programmer is online._\n\n**Notification** — A sound or pop-up warning showing a new message arrived.\n_Turn off app notifications._\n\n**Send** — Hitting the confirmation button to dispatch data.\n_Send the text message directly to me._\n\n**Read** — Confirming visually that a sent message was viewed.\n_He read my message but didn''t reply._\n\n**Screen** — The glass display surface on a laptop or smartphone.\n_Look at the chart on my screen._\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
