INSERT INTO courses.steps (id, lesson_id, type, title, content, order_index, created_at, updated_at)
VALUES ('e0a4e81d-203d-5511-8f4a-33cf717c3b81', 'b27f3bd6-9c3b-58ba-baf2-7dd5f2c4aa6b', 'text', 'Vocabulary', '{"text": "## Saving Your Work\n\n**Save** — To store your work safely on a computer so it is not lost.\n_Always save your document._\n\n**Work** — The text, code, or data you create.\n_Don''t forget to save your daily work._\n\n**Button** — A small digital box you click to run a command.\n_Click the top save button._\n\n**Change** — New details or edits made to a document.\n_Save your structural changes now._\n\n**Close** — To shut down a file or app on your screen.\n_Save the project before you close it._\n\n**Lost** — Missing or gone because it wasn''t stored.\n_My text is lost because the power went off._\n\n**Safe** — Protected from danger or loss.\n_Your digital files are completely safe here._\n\n**Keep** — To hold onto or preserve something.\n_Keep a backup copy of this document._\n\n**Document** — A formal piece of writing or text on a computer.\n_Name the new document clearly._\n\n**Auto-save** — A feature where the computer stores work by itself.\n_The app has a helpful auto-save feature._\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
