INSERT INTO courses.steps (id, lesson_id, type, title, content, order_index, created_at, updated_at)
VALUES ('9de0a223-e401-5f99-8efa-606189894261', '86223398-e67f-5840-9ed2-819123aa836a', 'text', 'Vocabulary', '{"text": "## Making a Mistake / Undo\n\n**Mistake** — Something that is incorrect or done wrong.\n_I made a small mistake in the count._\n\n**Undo** — A computer command that removes the last action you did.\n_Press undo to fix the text._\n\n**Wrong** — Not correct; containing errors.\n_This email address is completely wrong._\n\n**Back** — Returning to an earlier step or state.\n_Go back one step to fix the line._\n\n**Fix** — To make something correct or repair an error.\n_Let me fix this number quickly._\n\n**Delete** — To erase text, data, or files completely.\n_Delete this sentence from the page._\n\n**Eraser** — A tool used to remove pencil writing from paper.\n_Do you have an eraser I can use?_\n\n**Again** — Doing an action one more time.\n_Please type the customer name again._\n\n**Problem** — An issue that needs to be resolved.\n_Don''t worry, it is a tiny problem._\n\n**Correct** — Right, accurate, or true.\n_Is this the correct spelling of your name?_\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
