INSERT INTO courses.steps (id, lesson_id, type, title, content, order_index, created_at, updated_at)
VALUES ('e8d51e57-e2cb-522d-a5c6-b7072ce66364', '5e1ad677-d27c-5bf6-a42e-d374183fadb5', 'text', 'Vocabulary', '{"text": "## Organizing Papers\n\n**Sort** — To arrange items into an orderly group or sequence.\n_Sort these receipts by date._\n\n**Box** — A container used to store physical office items.\n_Put the old folders in this box._\n\n**Pile** — Objects positioned one on top of the other.\n_There is a massive pile of paper on my desk._\n\n**File** — To place documents into an organized system.\n_Please file these forms in the cabinet._\n\n**Cabinet** — A piece of furniture with drawers for storage.\n_Keep the contracts in the metal cabinet._\n\n**Label** — A piece of paper with a name attached to an object.\n_Write a clear label for each folder._\n\n**Order** — A structured or neat arrangement.\n_Keep your workplace files in alphabetical order._\n\n**Desk** — The work surface where you sit.\n_Clear the loose paper off your desk._\n\n**Throw away** — To put useless trash into a bin.\n_Throw away those old test notes._\n\n**Bin** — A container where trash or paper waste goes.\n_The waste paper bin is under the table._\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
