INSERT INTO courses.steps (id, lesson_id, type, title, content, order_index, created_at, updated_at)
VALUES ('f12ce18c-3d94-5a7a-b4db-332c199a4a1d', 'd85c560c-a433-5cad-bcd0-004c8268814b', 'text', 'Vocabulary', '{"text": "## Simple Calculations (Numbers 1–20)\n\n**Count** — To calculate the total number of things.\n_Please count the new boxes._\n\n**Number** — A symbol or word indicating a quantity.\n_What is the final number on the list?_\n\n**Total** — The complete amount after adding everything up.\n_The total cost is fifteen dollars._\n\n**Plus** — Added to; a sign ($+$) showing addition.\n_Ten plus five equals fifteen._\n\n**Equals** — Is the same amount or value as ($=$).\n_Two plus two equals four._\n\n**How many** — A phrase used to ask about a total quantity.\n_How many staff members are here?_\n\n**More** — A larger or extra amount.\n_We need three more black pens._\n\n**Less** — A smaller amount of something.\n_This template requires less text._\n\n**Price** — The amount of money something costs.\n_Check the price of the office chair._\n\n**Cost** — The value needed to buy or make something.\n_The total cost is very low._\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
