INSERT INTO courses.steps (id, lesson_id, type, title, content, order_index, created_at, updated_at)
VALUES ('ad3dd94c-6848-5ac2-ac0e-f845c1eff23a', '333fa247-9e66-5bdb-b6e6-2297be0b26a0', 'text', 'Vocabulary', '{"text": "## Filling Out a Form\n\n**Form** — A document with blank spaces for your information.\n_Fill out this employment form._\n\n**Fill out** — To write down requested information in blanks.\n_Fill out your profile details._\n\n**First name** — Your personal given name.\n_My first name is Abdul._\n\n**Last name** — Your family name or surname.\n_Write your last name in block letters._\n\n**Sign** — To write your official handwritten signature.\n_Please sign your name at the bottom._\n\n**Date** — The exact day, month, and year.\n_Write today''s date on this line._\n\n**Age** — How many years old a person is.\n_Please enter your age on the form._\n\n**Country** — The nation where you live or come from.\n_My home country is Tajikistan._\n\n**Box** — A square blank space to check or write in.\n_Check the small box for ''Yes''._\n\n**Complete** — To finish filling all empty parts of a document.\n_The application form is complete._\n"}', 0, NOW(), NOW())
