INSERT INTO courses.steps (id, lesson_id, type, title, content, order_index, created_at, updated_at)
VALUES ('7bc4feec-a8d9-55cd-9212-9cb5a7f8ce34', '2f4307fc-9f0d-502f-b617-68c404472a4c', 'text', 'Vocabulary', '{"text": "## Writing an Invoice / Bill\n\n**Invoice** — A document showing a list of services and the money owed.\n_Send the invoice to the buyer._\n\n**Bill** — A piece of paper showing how much money you must pay.\n_The electricity bill arrived today._\n\n**Pay** — To give money in exchange for work or products.\n_Clients must pay their bills on time._\n\n**Money** — Coins or banknotes used to buy things.\n_We receive money for our export trade._\n\n**Service** — Work done by a professional for a client.\n_The invoice lists our digital service._\n\n**Send** — To dispatch an item or message to an address.\n_Send the invoice by email now._\n\n**Paid** — Money has already been given for a service.\n_This official invoice is fully paid._\n\n**Due** — Expected or required to be paid by a certain date.\n_The payment is due on Monday._\n\n**Customer** — A person or company that buys services.\n_The customer needs a copy of the bill._\n\n**Amount** — The specific quantity of money on a document.\n_What is the total invoice amount?_\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
