INSERT INTO courses.steps (id, lesson_id, type, title, content, order_index, created_at, updated_at)
VALUES ('942cac54-ee0e-5102-b176-7e0cdaac98b9', 'f8b5fd51-680a-5b9a-973f-4ae020181567', 'text', 'Vocabulary', '{"text": "## Checking Inventory / Stock\n\n**Stock** — The supply of goods available for use or sale.\n_We have high stock in the warehouse._\n\n**Box** — A cardboard container for packing logistics.\n_Check the boxes on the top shelf._\n\n**Item** — A single object or product in a list.\n_This item is out of stock today._\n\n**Shelf** — A flat horizontal board used to store objects.\n_Put the product on the wooden shelf._\n\n**Full** — Containing as much as possible; no empty space.\n_The warehouse is completely full._\n\n**Empty** — Containing nothing; having space for goods.\n_The plastic storage box is empty._\n\n**Count** — Verifying the quantity of physical goods.\n_Count the number of items on the shelf._\n\n**Missing** — Not in the correct place; lost.\n_Two boxes of paper are missing._\n\n**Product** — Something made or grown to be sold.\n_This is our top-selling export product._\n\n**Inventory** — The detailed list of all current stock.\n_We do an inventory check every month._\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
