INSERT INTO courses.steps (id, lesson_id, type, title, content, order_index, created_at, updated_at)
VALUES ('f3bf4d84-bbb4-5156-911a-b1e096744505', 'c424cd38-67b6-5bfe-873e-3dd3b51931a8', 'text', 'Vocabulary', '{"text": "## Taking a Break\n\n**Break** — A short rest time away from work duties.\n_Let''s take a 10-minute coffee break._\n\n**Lunch** — The meal eaten in the middle of the day.\n_I eat lunch at 1:00 PM._\n\n**Rest** — To stop working and relax your mind or body.\n_Sit down and take a quick rest._\n\n**Kitchen** — The room where office staff make tea or heat food.\n_See you in the kitchen._\n\n**Eat** — To put food into your mouth and swallow it.\n_I always eat my lunch in the office._\n\n**Drink** — To swallow a liquid like tea or water.\n_I want to drink a hot cup of tea._\n\n**Minutes** — Units of time equal to 60 seconds.\n_My lunch break is forty minutes long._\n\n**Outside** — Out of the physical building; in the open air.\n_I am walking outside for five minutes._\n\n**Talk** — To speak casually with a colleague.\n_We talk about family during our break._\n\n**Relax** — To become calm and free from work stress.\n_Take a minute to relax after the task._\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
