INSERT INTO courses.steps (id, lesson_id, type, title, content, order_index, created_at, updated_at)
VALUES ('59366292-485e-5420-834f-84dffa100a38', '24f18434-84c9-5c1e-b382-a6850e5076fd', 'text', 'Vocabulary', '{"text": "## Packing Your Bag / Going Home\n\n**Pack** — To put your personal things into a container or bag.\n_Pack your notebook and pen._\n\n**Bag** — A container made of leather or cloth used to carry things.\n_Put the laptop in your bag._\n\n**Home** — The house or place where you live.\n_I am going home at 5 PM._\n\n**Leave** — To walk away from the office building at the end of the day.\n_We leave work early on Friday._\n\n**Key** — The metal object used to lock up doors.\n_Do you have the office keys?_\n\n**Lock** — To close a door securely using a key.\n_Please lock the main office door._\n\n**Turn off** — To stop the power supply to an electronic item.\n_Turn off your computer monitor._\n\n**Light** — The electrical bulbs that make a room bright.\n_Turn off the office lights, please._\n\n**Goodbye** — Words spoken when parting from colleagues.\n_Goodbye, everyone! See you tomorrow._\n\n**Tomorrow** — The day after today.\n_We have a big project starting tomorrow._\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
