INSERT INTO courses.steps (id, lesson_id, type, title, content, order_index, created_at, updated_at)
VALUES ('a9bbb39a-26eb-5040-be77-2641668b9c5e', '48c3ed0c-93df-560f-989f-28eb3a07f298', 'text', 'Vocabulary', '{"text": "## Looking for a Job\n\n**Look for** — To try to find something you need.\n_I look for a new job every day._\n\n**Job** — The regular work you do to earn money.\n_He wants a full-time job._\n\n**Find** — To discover a job after searching.\n_I want to find a good office position._\n\n**Search** — To look through a website or newspaper for listings.\n_Search for employment online._\n\n**Website** — A place on the internet where jobs are posted.\n_Check this recruitment website._\n\n**Ad / Advertisement** — A public notice offering a job position.\n_I am reading a job ad._\n\n**New** — Not existing or seen before.\n_There are many new vacancies today._\n\n**Work** — Employment or professional activity.\n_I want to start work next week._\n\n**Open** — Available for people to apply to.\n_The assistant position is still open._\n\n**Free** — Not busy; available to take a job.\n_I am free to start immediately._\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
