INSERT INTO courses.steps (id, lesson_id, type, title, content, order_index, created_at, updated_at)
VALUES ('d7219462-8469-5980-8366-919680727712', '2936eaf4-9e3b-5c77-9cf6-3d126e29680f', 'text', 'Vocabulary', '{"text": "## Writing a CV / Resume\n\n**CV / Resume** — A document showing your work history and education.\n_Send your CV to the manager._\n\n**Write** — To put words on paper or a computer file.\n_I need to write my resume today._\n\n**Page** — A sheet of paper or text on a screen.\n_Keep your CV on one page._\n\n**Info / Information** — Facts or details about yourself.\n_Include your contact info here._\n\n**History** — A record of your past work roles.\n_Write your employment history clearly._\n\n**School** — The place where you studied or took courses.\n_List your high school or college name._\n\n**Skills** — Things you do well, like computer coding or languages.\n_What are your professional skills?_\n\n**Language** — The system of communication you speak.\n_English is an important language for work._\n\n**Email** — Your digital address on your CV.\n_Put your professional email at the top._\n\n**File** — The digital document format.\n_Save your CV file as a PDF document._\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
