INSERT INTO courses.steps (id, lesson_id, type, title, content, order_index, created_at, updated_at)
VALUES ('90a35571-bab6-506c-8774-59eaaf7adbfe', 'f8d8a25d-e20b-5786-b7d5-660a95324c03', 'text', 'Vocabulary', '{"text": "## Sending an Application\n\n**Apply** — To formally ask for a job by sending documents.\n_Apply for the designer job online._\n\n**Send** — To dispatch your application by email or mail.\n_Send the documents to reception._\n\n**Attach** — To connect a digital file to an email.\n_Please attach your resume here._\n\n**Email** — The digital message system used to apply.\n_Write a brief cover email._\n\n**Click** — To press the action button on a screen.\n_Click the blue apply button._\n\n**Subject** — The title text of your application email.\n_Use the subject line ''Job Application''._\n\n**Letter** — A document explaining why you want the job.\n_Attach your application letter._\n\n**Please** — A polite word used in requests.\n_Please accept my application form._\n\n**Direct** — Going straight to the person in charge.\n_Send it direct to the hiring manager._\n\n**Wait** — To stay expectant for an answer.\n_Now, I wait for a response._\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
