INSERT INTO courses.steps (id, lesson_id, type, title, content, order_index, created_at, updated_at)
VALUES ('52d5e1af-bfbf-5575-8186-56d0aea19217', 'ce503357-579f-5f5f-8f66-28ce01fc827c', 'text', 'Vocabulary', '{"text": "## The Interview Invite\n\n**Call** — A telephone request or conversation about a job.\n_I received a phone call for an interview._\n\n**Invite** — A request asking you to come for a meeting.\n_Check your inbox for the interview invite._\n\n**Date** — The specific calendar day of the meeting.\n_What is the date of the interview?_\n\n**Time** — The hour the meeting starts on the clock.\n_The interview time is 10:00 AM._\n\n**Day** — The day of the week for the appointment.\n_The meeting is on Tuesday._\n\n**Come** — To arrive at the physical office location.\n_Please come to our main building._\n\n**Address** — The specific location of the company office.\n_Write down the street address._\n\n**Map** — A visual guide to find the location.\n_Look at the office location on the map._\n\n**Link** — A digital address for an online video call.\n_Click the link to join the online interview._\n\n**Happy** — Feeling pleased about getting a chance.\n_I am very happy to get this invite._\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
