INSERT INTO courses.steps (id, lesson_id, type, title, content, order_index, created_at, updated_at)
VALUES ('4ce20d8c-ca87-5d15-a25e-172ddfdc6326', '9067607d-6a1f-5e06-af15-bb6043cc28fb', 'text', 'Vocabulary', '{"text": "## Arriving for the Interview\n\n**Arrive** — To reach the destination workspace.\n_Please arrive fifteen minutes early._\n\n**Early** — Before the exact scheduled time.\n_It is good to be early for a meeting._\n\n**Reception** — The front desk area where visitors arrive.\n_Go straight to the office reception._\n\n**Name** — Your identity word used to check in.\n_Give your full name to the receptionist._\n\n**Sit** — To take a seat while waiting.\n_Please sit down on the sofa._\n\n**Wait** — To stay in the lobby until called.\n_Wait here for the manager, please._\n\n**Clothes / Dress** — What you wear to look professional.\n_Wear clean, professional clothes._\n\n**Hello** — A polite standard greeting when you enter.\n_Hello, I am here for an interview._\n\n**Smile** — To make a pleasant facial expression.\n_Smile when you meet the team._\n\n**Ready** — Fully prepared to start the conversation.\n_I am completely ready for the meeting._\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
