INSERT INTO courses.steps (id, lesson_id, type, title, content, order_index, created_at, updated_at)
VALUES ('3092b116-07e1-55aa-9c40-f3467771798b', '2c23c3c7-521f-5078-b45b-1cf7fde44b09', 'text', 'Vocabulary', '{"text": "## Introducing Yourself\n\n**Name** — What people call you.\n_My name is Abdul._\n\n**From** — Showing your home city or country.\n_I am from Tajikistan._\n\n**Experience** — Time spent doing a job in the past.\n_I have five years of work experience._\n\n**Years** — The units of time spent in a profession.\n_I worked as an engineer for three years._\n\n**Speak** — To talk in a specific language.\n_I speak English and Tajik._\n\n**Study** — To learn a subject at a school or university.\n_I studied business at university._\n\n**Like** — To enjoy doing a certain work activity.\n_I like working with a big team._\n\n**Good at** — Able to do something well.\n_I am very good at managing documents._\n\n**Learn** — To get new knowledge or skills.\n_I want to learn new digital tools._\n\n**Me** — Referring to yourself.\n_Let me tell you about my career history._\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
