INSERT INTO courses.steps (id, lesson_id, type, title, content, order_index, created_at, updated_at)
VALUES ('2eafdd41-80f0-5736-b97d-3deb74c0bf9e', 'c8b0877a-b01f-52d0-b443-ea928294538c', 'text', 'Vocabulary', '{"text": "## Answering Interview Questions\n\n**Question** — The sentence the manager asks you.\n_Listen to the interview question carefully._\n\n**Answer** — The information you give after a question.\n_Give a short, clear answer._\n\n**Why** — Asking for the reason you want the role.\n_Why do you want to work for our company?_\n\n**Because** — Used to give a reason for your answer.\n_Because I like your premium global brand._\n\n**Yes** — A positive confirmation.\n_Yes, I can use this software application._\n\n**No** — A negative answer or denial.\n_No, I do not mind working on Saturdays._\n\n**Example** — A specific time you did a task in the past.\n_Let me give you a quick example._\n\n**True** — Honest and correct facts.\n_Always give true information about your skills._\n\n**Think** — To use your mind to form an opinion.\n_I think I am a good worker for this job._\n\n**Understand** — Knowing the meaning of what is asked.\n_I understand the question completely._\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
