INSERT INTO courses.steps (id, lesson_id, type, title, content, order_index, created_at, updated_at)
VALUES ('e6b40e28-2914-5a61-bf2d-f3a80bd2e5b0', 'c3f26ef0-f46e-5d3b-9b80-41ba993e8c86', 'text', 'Vocabulary', '{"text": "## My Strengths / What I Can Do\n\n**Can** — Having the ability to do a task.\n_I can speak English fluently._\n\n**Fast** — Doing work quickly without losing quality.\n_I am a very fast learner._\n\n**Hard** — Working with a lot of effort and energy.\n_He is a hard worker for our office._\n\n**Help** — To assist other team members.\n_I can help colleagues with technical problems._\n\n**Know** — Having clear information inside your mind.\n_I know how to run marketing ads._\n\n**Use** — To operate a tool or machine for a task.\n_I can use Excel and Word documents._\n\n**Team** — Working well with other office staff.\n_I am a strong team player._\n\n**Time** — Managing your schedule properly.\n_I arrive on time every day._\n\n**Organized** — Keeping your desk and files neat.\n_I am an organized professional._\n\n**Write** — Creating text communications accurately.\n_I can write professional emails._\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
