INSERT INTO courses.steps (id, lesson_id, type, title, content, order_index, created_at, updated_at)
VALUES ('a342efdc-c62f-582e-8044-3fd3ac403d7c', '045269d1-df62-5d44-b8be-bd3ad2f6cdd3', 'text', 'Vocabulary', '{"text": "## The Job Offer\n\n**Offer** — A formal letter or choice giving you the job.\n_I received a job offer from the firm._\n\n**Accept** — To say yes to the job proposal.\n_I am happy to accept your job offer._\n\n**Contract** — The official legal paper you sign for work.\n_Please read the employment contract._\n\n**Sign** — Writing your name to make the contract legal.\n_Sign the paper at the bottom line._\n\n**Start** — The first official day on the job.\n_My start date is next Monday morning._\n\n**Salary** — The agreed payment amount.\n_The starting salary is very good._\n\n**New** — Beginning a fresh role or position.\n_Welcome to your new job title._\n\n**Congratulate / Congratulations** — Words spoken to celebrate your success.\n_Congratulations on joining the team!_\n\n**Thank you** — Expressing your professional gratitude.\n_Thank you for this wonderful opportunity._\n\n**Employee** — A person who officially works for a company.\n_You are now an employee of this business._\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
