INSERT INTO courses.steps (id, lesson_id, type, title, content, order_index, created_at, updated_at)
VALUES ('dbc595d3-4cdd-59a1-ae75-1180b28b4fbf', '0b304158-ec41-554c-b9ae-6e33c966c855', 'text', 'Vocabulary', '{"text": "## Dress Code / Rules\n\n**Rule** — An official instruction about what you must or must not do.\n_Follow the office rules._\n\n**Dress** — The style of clothes worn at work.\n_We have a professional dress code._\n\n**Wear** — To have clothes, shoes, or suits on your body.\n_Please wear a clean shirt to work._\n\n**Suit** — A formal set of clothes with a jacket and trousers or a skirt.\n_He wears a dark suit for meetings._\n\n**Casual** — Informal, comfortable clothes like jeans and t-shirts.\n_On Friday, we wear casual clothes._\n\n**Formal** — Very neat, traditional clothes for business.\n_The client meeting requires formal dress._\n\n**Shirt** — A standard top garment with a collar and sleeves.\n_My work shirt is white._\n\n**Clean** — Not dirty or messy.\n_Always wear clean clothes to the office._\n\n**Policy** — The company''s official general guidelines.\n_Check the company policy on uniforms._\n\n**No** — Used to show that something is forbidden.\n_There are no casual shoes allowed on Monday._\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
