INSERT INTO courses.steps (id, lesson_id, type, title, content, order_index, created_at, updated_at)
VALUES ('84028ec4-6943-5753-9130-d7eddf714fbd', 'fe619f35-ee83-5499-987d-4baec41393cd', 'text', 'Vocabulary', '{"text": "## Workplace Safety Basics\n\n**Safe / Safety** — Protection from danger, harm, or accidents.\n_Workplace safety is very important._\n\n**Danger** — Something that can cause harm or injury.\n_Stay away from the construction danger zone._\n\n**Careful** — Giving attention to avoid accidents.\n_Be careful when using the big machine._\n\n**Exit** — The door or way out of a building.\n_The emergency exit is near the stairs._\n\n**Fire** — Destructive heat and flames.\n_Know what to do in case of an office fire._\n\n**Helmet / Hat** — A hard hat worn to protect your head.\n_Wear a safety helmet inside the factory._\n\n**Boots** — Heavy protective shoes for manual work.\n_Put on your safety boots before entering._\n\n**Floor** — The surface you walk on inside the building.\n_The kitchen floor is wet and slippery._\n\n**Wet** — Covered with water or liquid.\n_Be careful, the stairs are wet._\n\n**Help** — Assistance during an emergency.\n_Call for help if an accident happens._\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
