INSERT INTO courses.steps (id, lesson_id, type, title, content, order_index, created_at, updated_at)
VALUES ('838b7da8-405d-5aee-a18d-6d74634d3b05', '39ee6189-750a-54f3-9a2a-fc5571e5aecd', 'text', 'Vocabulary', '{"text": "## Sick Leave & Absences\n\n**Sick** — Not feeling well; having an illness.\n_I cannot come to work because I am sick._\n\n**Leave** — Time away from your job with permission.\n_I am taking two days of sick leave._\n\n**Home** — Staying in your house to rest.\n_Stay home and rest if you have a fever._\n\n**Doctor** — A medical professional who treats ill people.\n_I need to visit the family doctor today._\n\n**Note / Paper** — A written document from a doctor confirming your illness.\n_Bring a medical note to HR._\n\n**Call** — Phoning your supervisor to report an absence.\n_Call the manager before 9:00 AM._\n\n**Inform** — To give information or notify your team.\n_Please inform the staff about your absence._\n\n**Message** — A brief text sent to update your coworker.\n_Send an update message to the supervisor._\n\n**Out** — Away from the office environment.\n_Anna is out today due to illness._\n\n**Better** — Feeling healthier than before.\n_I hope you feel better soon._\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
