INSERT INTO courses.steps (id, lesson_id, type, title, content, order_index, created_at, updated_at)
VALUES ('d4cebaca-c798-58ca-bbdf-1ec674e5cfa7', '702f58cc-b378-58fd-a425-3b77cc78db55', 'text', 'Vocabulary', '{"text": "## Requesting Time Off / Vacation\n\n**Holiday / Vacation** — A period of rest away from work or travel.\n_I want to take a summer holiday._\n\n**Ask for** — To request permission for something.\n_I need to ask for three days off._\n\n**Days** — The count of calendar days requested.\n_He wants five days of winter vacation._\n\n**Form** — The paper or digital screen used to submit a request.\n_Fill out the time-off form._\n\n**Approve** — When a manager says yes to a request.\n_Did the boss approve your vacation?_\n\n**Next** — Coming immediately after this one.\n_I am going on holiday next month._\n\n**Dates** — The specific start and end points of a trip.\n_Write your vacation dates on the calendar._\n\n**Manager** — The person who permits your time off.\n_Speak to your direct manager first._\n\n**Off** — Not working on a standard business day.\n_I have next Tuesday off._\n\n**Trip** — A journey or travel experience.\n_Have a wonderful, safe trip!_\n"}', 0, NOW(), NOW())
