INSERT INTO courses.steps (id, lesson_id, type, title, content, order_index, created_at, updated_at)
VALUES ('45ace402-b95f-50be-92cf-d6256f71cb13', '4d2f10dc-5f72-57f4-9d09-cd5f30c2478b', 'text', 'Vocabulary', '{"text": "## My First Paycheck\n\n**Pay / Paycheck** — The money you receive for doing your job.\n_I get my first paycheck today._\n\n**Bank** — The financial business where your money is safely kept.\n_The salary goes directly to my bank._\n\n**Account** — Your personal profile arrangement with a bank.\n_Give your account number to HR._\n\n**Cash** — Money in the physical form of coins or paper notes.\n_Does the firm pay in cash or card?_\n\n**Card** — A plastic debit or credit card used to get money.\n_I use my bank card at the machine._\n\n**Month** — The standard four-week period for pay cycles.\n_We receive our salary every month._\n\n**Money** — What you earn for your daily labor.\n_It is nice to earn your own money._\n\n**Day** — The specific recurring date when salary arrives.\n_Friday is our official payday._\n\n**Check** — To verify that the money arrived.\n_Log in to check your bank balance._\n\n**First** — Coming at the very beginning of your employment history.\n_My first salary is exciting._\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
