INSERT INTO courses.steps (id, lesson_id, type, title, content, order_index, created_at, updated_at)
VALUES ('ed29c370-8200-56aa-9cea-33c4c4d76281', '2da07f38-a78e-5145-ad90-e8a8bc075a42', 'text', 'Vocabulary', '{"text": "## Asking About a Promotion\n\n**Move up / Promotion** — Moving up to a higher, better position at work.\n_She wants a promotion to manager._\n\n**High / Higher** — A position above your current role.\n_I want to reach a higher level._\n\n**New** — A fresh set of responsibilities.\n_She is ready for a new professional role._\n\n**Talk** — To discuss your career development with a leader.\n_Talk to the supervisor about your future._\n\n**Ready** — Prepared to take on bigger tasks.\n_I am ready for more responsibility._\n\n**More** — An additional amount of duties or targets.\n_A higher job means more work._\n\n**Role** — A specific position or duty inside a team.\n_What is your new team role?_\n\n**Future** — The time that is still to come.\n_Think about your long-term career future._\n\n**Boss** — The person who decides on rank changes.\n_Ask the boss for a brief meeting._\n\n**Growth** — The process of developing or improving skills.\n_This corporate role offers good career growth._\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
