INSERT INTO courses.steps (id, lesson_id, type, title, content, order_index, created_at, updated_at)
VALUES ('26b050ca-a131-5225-be82-8c276410ec1e', '1af90a4e-f64d-55dd-bea0-70f21fa4fe09', 'text', 'Vocabulary', '{"text": "## Getting a Pay Raise\n\n**Raise** — An increase in the amount of money you earn.\n_I want to ask for a pay raise._\n\n**More** — An extra amount of salary added to your check.\n_I need to earn more money._\n\n**Hard** — Working with great effort to show value.\n_I work hard every single day._\n\n**Meeting** — A formal sitting to talk about money values.\n_Schedule a salary meeting with HR._\n\n**Ask** — Requesting a higher wage rate.\n_It is time to ask for a pay increase._\n\n**Year** — The 12-month mark when salaries are reviewed.\n_I worked here for a whole year._\n\n**Good** — Showing strong results to justify a raise.\n_You did a very good job this quarter._\n\n**Deserve** — Earning something because of your good work history.\n_You deserve a higher salary._\n\n**Performance** — How well an employee does their tasks.\n_Your monthly performance is excellent._\n\n**Review** — A formal assessment of your workplace outputs.\n_We have an annual salary review._\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
