INSERT INTO courses.steps (id, lesson_id, type, title, content, order_index, created_at, updated_at)
VALUES ('983293cc-7d8e-5e64-8e88-a82778fe9fb3', 'e3d1accd-1666-5af2-bbd8-a0a7213c56f5', 'text', 'Vocabulary', '{"text": "## Resigning / Leaving the Company\n\n**Leave** — To exit or quit your current job permanently.\n_I plan to leave the company next month._\n\n**Resign / Quit** — Formally stating that you are stopping your work.\n_He decided to resign from his position._\n\n**New** — A fresh company or position you are moving to.\n_I found a wonderful new job opportunity._\n\n**Letter** — A formal document stating you are quitting.\n_Give your resignation letter to the manager._\n\n**Last** — The final day you spend inside the office.\n_Friday is my last day of work._\n\n**Notice** — Advance time given to an employer before you leave.\n_Give a standard two-week notice._\n\n**Say** — Communicating your decision to your supervisor.\n_I need to say goodbye to the director._\n\n**Change** — Making a switch to a different career pathway.\n_I need a professional change in my life._\n\n**Team** — The group of colleagues you are leaving behind.\n_Inform your core team about the move._\n\n**Thank** — Expressing gratitude for past support.\n_Thank your team for the great experience._\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
