INSERT INTO courses.steps (id, lesson_id, type, title, content, order_index, created_at, updated_at)
VALUES ('f42f0242-9592-5c71-818f-5744beca9bcb', 'bb2ad659-fe92-542e-883f-e36ca42dae5f', 'text', 'Vocabulary', '{"text": "## Retirement Basics\n\n**Stop** — To end your active working years forever because of age.\n_My father is ready to stop work._\n\n**Old** — Having lived for many years.\n_He is sixty-five years old now._\n\n**Retire** — To stop working permanently, usually at age 60–65.\n_I want to retire and travel the world._\n\n**Rest** — To relax and live without the stress of daily work.\n_Now it is time to sit down and rest._\n\n**Free** — Having absolute open time with no corporate duties.\n_Retired people have a lot of free time._\n\n**Pension** — Regular money paid by the government or company after retirement.\n_He receives a monthly pension._\n\n**Family** — Relatives you spend time with after your career finishes.\n_Spend time at home with your family._\n\n**Age** — The point in life when you are allowed to stop work.\n_What is the official retirement age here?_\n\n**Life** — The daily experience after your employment history closes.\n_Enjoy your peaceful post-work life._\n\n**Celebration** — A party or event to honor a long career.\n_The office is hosting a retirement celebration._\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
