INSERT INTO courses.steps (id, lesson_id, type, title, content, order_index, created_at, updated_at)
VALUES ('80984943-6256-5ada-ae76-2436bcf1ca87', '1cc466f7-1d1d-552f-82cc-b1199a3671f4', 'text', 'Vocabulary', '{"text": "## The Farewell Party\n\n**Party** — A social gathering to celebrate someone''s departure or achievement.\n_We have a farewell party today._\n\n**Gift / Present** — An item given to a departing colleague to say thank you.\n_Buy a nice gift for the coworker._\n\n**Card** — A folded paper with signed good wishes from the staff.\n_Please sign the farewell card._\n\n**Say** — Expressing a final parting phrase.\n_Come to the kitchen to say goodbye._\n\n**Goodbye** — The parting word used when an employee leaves.\n_We must say goodbye to our friend._\n\n**Cake** — A sweet baked dessert shared at office gatherings.\n_We have a chocolate cake for the party._\n\n**Luck / Best wishes** — Wishing someone success in their future roles.\n_Good luck in your new career path!_\n\n**Remember** — To keep a person or memory in your mind.\n_We will always remember your hard work._\n\n**Friend** — A close or kind colleague at the office.\n_You are a very good work friend._\n\n**Miss** — Feeling sad because a great colleague is no longer there.\n_The entire team will miss you here._\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
